// entry: MainSub04:1268-1280; dependency: GirlB01:542-566, GirlB01_at:568-608.
// MainSub04 spawns five GirlB01 at world (0/32/-32/64/-64, -24); the stage parent is
// at (0,0), so enmCreate's relative input is the world position.

// 970 = 120 buffer + 846 source frames + 4 startup margin. Measured Lunatic tail:
// last shot at source ~491; upward-fired bullets curve back down and the last
// on-screen one leaves at source ~842. The 650 estimate in task.md was short for
// this curved tail.
const TIME_LIMIT: int = 970;
const OPENING_BUFFER: int = 120;

// etSprite(0, 8, 6): source type 8 = TH16_RICE, color 6.
const TH16_RICE: int = 480;

// GirlB01_at etEx(0, 0, 4, 1200, ..., 0.01f, 1.5707964f):
// ACCEL with duration 1200, scalar 0.01 px/frame^2 toward angle pi/2 (down).
// The earlier etEx(0, 0, 2, 1, ...) is ANIM a=1; its only retained effect here is the
// birth back-displacement position -= 4 * velocity, applied at the fire position below.
xformdef TH16_ACCEL_DOWN {
    set_gravity(0fx, 0.01fx);
    wait(1200);
    set_gravity(0fx, 0fx);
}

// GirlB01_at: one fixed-direction ring of 1x1, re-aimed by etAngle before each etOn.
async sub girl_b01_at() {
    var a: angle = 90deg;   // %A = 1.5707964f
    var b: int = 1;         // $B = 1
    var c: int = 0;         // diffI($C, 30, 80, 120, 160)
    var rank: int = global(GVAR_RANK);
    if rank == 0 { c = 30; }
    else if rank == 1 { c = 80; }
    else if rank == 2 { c = 120; }
    else { c = 160; }
    if rank == 0 { wait(30); }   // source !E wait(30)
    while c > 0 {
        c = c - 1;               // source if ($C--) goto GirlB01_at_440
        // etAngle(0, %A, 0); %A += 3.883222f; etOn(0)
        var px: fx = $self_x - 4fx * cos(a);
        var py: fx = $self_y - 4fx * sin(a);
        _ = fire(TH16_RICE, 6, px, py, 1fx, a, TH16_ACCEL_DOWN, none);
        a = a + (40503 as angle);   // 3.883222 rad
        // unless (($B % 4) != 0) goto GirlB01_at_780: wait only when B % 4 != 0.
        if b % 4 != 0 {
            if rank == 0 { wait(2); } else { wait(1); }   // source !E 2; !N !H !LO 1
        }
        if rank >= 2 { b = b + 1; }   // source !HL
    }
}

// GirlB01: movement and the async firing task.
async sub girl_b01() {
    set_invuln(65535);
    set_hurtbox(16fx);   // setHurtbox(32, 32) -> radius 16
    set_hitbox(12fx);    // setHitbox(24, 24) -> radius 12
    move_vel(0, 90deg, 3.3fx, EASE_LINEAR);    // moveVel(1.5707964f, 3.3f)
    move_speed(80, 0fx, EASE_QUAD_IN);         // moveVelTime(80, 1, -999999, 0.0f)
    spawn girl_b01_at();                       // @GirlB01_at() async
    wait(240);
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);   // moveVel(%ANGLE_PLAYER, 0.0f)
    move_speed(80, 1fx, EASE_QUAD_IN);             // moveVelTime(80, 1, -999999, 1.0f)
    wait(60);
    loop { wait(1000); }
}

// MainSub04: spawn intervals 120/120/80/50, hp 800 then 700.
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, -24fx, 800, 0, 0, 0, girl_b01);
    wait(120);
    _ = spawn_enemy(32fx, -24fx, 700, 0, 0, 0, girl_b01);
    wait(120);
    _ = spawn_enemy(-32fx, -24fx, 700, 0, 0, 0, girl_b01);
    wait(80);
    _ = spawn_enemy(64fx, -24fx, 700, 0, 0, 0, girl_b01);
    wait(50);
    _ = spawn_enemy(-64fx, -24fx, 700, 0, 0, 0, girl_b01);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
